import React, { useState, useRef, useEffect } from 'react';
import { initWebGL, processFrameWebGL } from '../utils/webglProcessor';

const CameraProcessor = ({ colorblindType, mode }) => {
  const [streaming, setStreaming] = useState(false);
  const [error, setError] = useState(null);
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const glRef = useRef(null);
  const streamRef = useRef(null);
  const animationFrameRef = useRef(null);

  useEffect(() => {
    return () => {
      stopCamera();
    };
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { width: 1280, height: 720 }
      });
      
      streamRef.current = stream;
      
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        videoRef.current.play();
        setStreaming(true);
        setError(null);
        
        if (canvasRef.current) {
          const gl = initWebGL(canvasRef.current);
          glRef.current = gl;
          processFrames();
        }
      }
    } catch (err) {
      setError('Failed to access camera: ' + err.message);
      setStreaming(false);
    }
  };

  const stopCamera = () => {
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
      streamRef.current = null;
    }
    
    if (animationFrameRef.current) {
      cancelAnimationFrame(animationFrameRef.current);
      animationFrameRef.current = null;
    }
    
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    
    setStreaming(false);
  };

  const processFrames = async () => {
    if (!videoRef.current || !canvasRef.current || !streaming) return;
    
    const video = videoRef.current;
    const canvas = canvasRef.current;
    
    if (video.readyState === video.HAVE_ENOUGH_DATA) {
      if (glRef.current) {
        processFrameWebGL(glRef.current, video, canvas, colorblindType, mode);
      } else {
        const ctx = canvas.getContext('2d');
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        
        const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
        const data = imageData.data;
        
        for (let i = 0; i < data.length; i += 4) {
          const r = data[i];
          const g = data[i + 1];
          const b = data[i + 2];
          
          if (mode === 'simulate') {
            if (colorblindType === 'protanopia') {
              data[i] = r * 0.567 + g * 0.433;
              data[i + 1] = r * 0.558 + g * 0.442;
              data[i + 2] = g * 0.242 + b * 0.758;
            } else if (colorblindType === 'deuteranopia') {
              data[i] = r * 0.625 + g * 0.375;
              data[i + 1] = r * 0.7 + g * 0.3;
              data[i + 2] = g * 0.3 + b * 0.7;
            } else if (colorblindType === 'tritanopia') {
              data[i] = r * 0.95 + g * 0.05;
              data[i + 1] = g * 0.433 + b * 0.567;
              data[i + 2] = g * 0.475 + b * 0.525;
            }
          }
        }
        
        ctx.putImageData(imageData, 0, 0);
      }
    }
    
    animationFrameRef.current = requestAnimationFrame(processFrames);
  };

  return (
    <div className="component-container">
      <h2>Live Camera Feed</h2>
      
      <div
        className="upload-area"
        style={{ 
          textAlign: 'center',
          padding: '40px 20px',
          border: '2px dashed #ccc',
          borderRadius: '8px',
          backgroundColor: '#fafafa',
          cursor: streaming ? 'default' : 'pointer'
        }}
      >
        {!streaming ? (
          <>
            <p style={{ fontSize: '16px', marginBottom: '10px' }}>Ready to start live camera feed</p>
            <p style={{ fontSize: '14px', color: '#666', marginBottom: '20px' }}>
              Click the button below to activate your camera
            </p>
          </>
        ) : (
          <p style={{ fontSize: '16px' }}>Camera is active</p>
        )}
      </div>

      {error && <div className="error" style={{ marginTop: '15px' }}>{error}</div>}

      {streaming && (
        <div className="camera-container" style={{ marginTop: '20px' }}>
          <video
            ref={videoRef}
            style={{ display: 'none' }}
            width={1280}
            height={720}
          />
          <canvas
            ref={canvasRef}
            width={1280}
            height={720}
            style={{ maxWidth: '100%', height: 'auto', border: '2px solid #ddd', borderRadius: '8px', display: 'block', margin: '0 auto' }}
          />
        </div>
      )}

      <div style={{ textAlign: 'center', marginTop: '20px' }}>
        <button
          className="button"
          onClick={streaming ? stopCamera : startCamera}
        >
          {streaming ? 'Stop Camera' : 'Start Camera'}
        </button>
      </div>
    </div>
  );
};

export default CameraProcessor;
